export function emitWindBlades(e,m,c){const r=c.growth?.windBurst||0;if(m.id!==2||!r||(m.windBladeAt??-1)>e.time)return;m.windBladeAt=e.time+.3;const count=8+4*(r-1),distance=360;for(let i=0;i<count;i++){const a=i*Math.PI*2/count;e.projectiles.push({kind:'bladeWave',windBlade:true,rangeOwner:2,x:m.x,y:m.y-15,tx:m.x+Math.cos(a)*distance,ty:m.y-15+Math.sin(a)*distance,speed:560,damage:c.damage*(.5+.15*r),skill:c,color:'#83dac3',life:distance/560,trail:[],p:[],hits:new Set(),pierces:999,spin:false,r:18+4*r});}}
